param(
    [string]$Root = (Resolve-Path (Join-Path $PSScriptRoot '..')).Path
)

$ErrorActionPreference = 'Stop'
$utf8 = [System.Text.Encoding]::UTF8
$failures = New-Object System.Collections.Generic.List[string]
$decompiledRoot = if (-not [string]::IsNullOrWhiteSpace($env:JHYL_DECOMPILED_ROOT)) {
    $env:JHYL_DECOMPILED_ROOT
} else {
    Join-Path $Root '.decompiled'
}

function Read-Source([string]$RelativePath) {
    $path = Join-Path $Root $RelativePath
    if (-not (Test-Path $path)) {
        $failures.Add("Missing source file: $RelativePath")
        return ''
    }
    return [System.IO.File]::ReadAllText($path, $utf8)
}

function Assert-Contains([string]$Name, [string]$Text, [string]$Needle) {
    if ($Text.IndexOf($Needle, [System.StringComparison]::Ordinal) -lt 0) {
        $failures.Add($Name)
    }
}

function Assert-NotContains([string]$Name, [string]$Text, [string]$Needle) {
    if ($Text.IndexOf($Needle, [System.StringComparison]::Ordinal) -ge 0) {
        $failures.Add($Name)
    }
}

function Assert-Match([string]$Name, [string]$Text, [string]$Pattern) {
    if ($Text -notmatch $Pattern) {
        $failures.Add($Name)
    }
}

function Assert-CountEquals([string]$Name, [string]$Text, [string]$Needle, [int]$Expected) {
    $count = 0
    $at = $Text.IndexOf($Needle, [System.StringComparison]::Ordinal)
    while ($at -ge 0) {
        $count++
        $at = $Text.IndexOf($Needle, $at + $Needle.Length, [System.StringComparison]::Ordinal)
    }
    if ($count -ne $Expected) {
        $failures.Add("$Name (expected $Expected, found $count)")
    }
}

function Assert-Before([string]$Name, [string]$Text, [string]$First, [string]$Second) {
    $firstAt = $Text.IndexOf($First, [System.StringComparison]::Ordinal)
    $secondAt = $Text.IndexOf($Second, [System.StringComparison]::Ordinal)
    if ($firstAt -lt 0 -or $secondAt -lt 0 -or $firstAt -ge $secondAt) {
        $failures.Add($Name)
    }
}

function Assert-BlockNotContains([string]$Name, [string]$Text, [string]$Start, [string]$End, [string]$Needle) {
    $startAt = $Text.IndexOf($Start, [System.StringComparison]::Ordinal)
    $endAt = if ($startAt -ge 0) { $Text.IndexOf($End, $startAt + $Start.Length, [System.StringComparison]::Ordinal) } else { -1 }
    if ($startAt -lt 0 -or $endAt -lt 0 -or $endAt -le $startAt) {
        $failures.Add("$Name (block not found)")
        return
    }
    $block = $Text.Substring($startAt, $endAt - $startAt)
    if ($block.IndexOf($Needle, [System.StringComparison]::Ordinal) -ge 0) {
        $failures.Add($Name)
    }
}

