try {
    $specialManifestObject = $specialManifest | ConvertFrom-Json
    $jinhuangManifestEntry = $specialManifestObject.entries | Where-Object { $_.key -eq 'jinhuang' } | Select-Object -First 1
    if ($null -eq $jinhuangManifestEntry -or @($jinhuangManifestEntry.characterTemplateIds) -contains 222) {
        $failures.Add('Wooden Jinhuang template is not routed as Jinhuang')
    }
    $exactIds = @($specialManifestObject.entries | Where-Object { $_.role -eq 'character' } |
        ForEach-Object { @($_.characterTemplateIds) } | ForEach-Object { [int]$_ })
    $expectedExactIds = @(66..74) + @(147..155) + @(204,213,877,878,879,913,916,917,918) +
        @(for ($id = 969; $id -le 1011; $id += 2) { $id }) + @(1091,1113)
    if (@($exactIds | Sort-Object -Unique).Count -ne 51 -or
        [string]::Join(',', @($exactIds | Sort-Object -Unique)) -ne [string]::Join(',', @($expectedExactIds | Sort-Object -Unique))) {
        $failures.Add('Special persona manifest does not contain the exact authoritative 51 TemplateIds')
    }
    foreach ($excluded in @(222,1277,1278,1279)) {
        if ($exactIds -contains $excluded) { $failures.Add("Excluded wooden template is routed as a real character: $excluded") }
    }
    $fallback = $specialManifestObject.cricketFallback
    $maleIds = @($fallback.maleTemplateIds | ForEach-Object { [int]$_ })
    $femaleIds = @($fallback.femaleTemplateIds | ForEach-Object { [int]$_ })
    if ($fallback.maleResourceFile -ne 'persona-cricket-common-male.txt' -or
        $fallback.femaleResourceFile -ne 'persona-cricket-common.txt') {
        $failures.Add('Cricket fallback resources are not explicitly gender-separated')
    }
    for ($id = 968; $id -le 1011; $id++) {
        $inMale = $maleIds -contains $id
        $inFemale = $femaleIds -contains $id
        if (($id % 2 -eq 0 -and (-not $inMale -or $inFemale)) -or
            ($id % 2 -ne 0 -and (-not $inFemale -or $inMale))) {
            $failures.Add("Cricket TemplateId gender map is incomplete or crossed: $id")
        }
    }
} catch { $failures.Add('Special persona manifest parses for template audit') }

