function Read-DecompiledSource([string]$RelativePath) {
    $path = Join-Path $decompiledRoot $RelativePath
    if (-not (Test-Path -LiteralPath $path)) {
        $failures.Add("Missing decompiled source file: $path")
        return ''
    }
    return [System.IO.File]::ReadAllText($path, $utf8)
}
