Assert-Contains 'Failed import rounds stay retryable instead of being sealed' $paths 'JHYL_LEGACY_IMPORT_RETRYABLE'
# P2 认领粒度:按文件名内嵌太吾 id 认领;新代码不再写全局先到先得标记(只读旧标记保持兼容)。
