# P2 复制失败窗口:逐文件容错 + 失败清单 + 玩家可见提示;不再一个坏文件阻断全部 kind。
Assert-Contains 'Legacy copy is per-file fault tolerant' $paths 'JHYL_LEGACY_IMPORT_PER_FILE_TOLERANT'
Assert-Contains 'Per-file copy failures are recorded and skipped' $paths 'catch (Exception e) { failures.Record(file, e); }'
Assert-Contains 'Persistent import failures surface a player-visible notice' $paths 'LegacyDataNotice.Post("legacy-import-failures-'
