# 流式聊天只结算自己的内容布局，不得每个 token 强制重建整个游戏 Canvas。
Assert-Contains 'Chat scroll rebuilds only the local content layout' $chatWindow 'LayoutRebuilder.ForceRebuildLayoutImmediate(_content);'
Assert-NotContains 'Chat streaming no longer forces a global canvas rebuild' $chatWindow 'Canvas.ForceUpdateCanvases();'

# “身上带着行医积淀/身上有一层坦荡”是稳定性格修辞，不是实时背包。
Assert-Contains 'Portrait runtime filter limits bare 身上 possession to concrete inventory verbs' $portraitDistiller '(?:身上)(?:携带|持有|备有|藏有|拿着)'
Assert-NotContains 'Portrait runtime filter no longer treats every 身上有/带着 metaphor as inventory' $portraitDistiller '|身上|手里|囊中)(?:有|带有|带着'
# #2(P1) reasoning_effort 仅对确支持的推理模型下发 + 运行期拒收后剥离重试,防非推理端每轮400。
$providerCapabilities2 = Read-Source 'src/JianghuYouling.Core/Llm/ProviderCapabilities.cs'
Assert-Contains 'reasoning_effort is gated to a precise capability bit' $providerCapabilities2 'c.SupportsReasoningEffort = c.IsOpenAiReasoningChat'
Assert-Contains 'reasoning_effort only sent when capability bit set and not rejected' $llmClient 'policy != LlmReasoningPolicy.Auto && _capabilities.SupportsReasoningEffort && !_reasoningEffortRejected'
Assert-Contains 'reasoning_effort rejection is probed and memoized to strip on retry' $llmClient 'private static bool LooksLikeReasoningEffortRejected(string err)'
# #3(P3) 不透明 provider 元数据(thought_signature)只做精确密钥比对,不跑宽口径正则误报。
Assert-Contains 'Opaque provider metadata uses exact-secret check not broad redaction regex' $llmClient 'ContainsExactSecret'
# #4 Gemini 3: official Google remains strict; non-Google OpenAI-compatible gateways may use
# Google's documented history sentinel when the gateway stripped the real signature.
Assert-Contains 'Gemini compatibility uses the documented Google validator sentinel' $llmClient 'GeminiSignatureCompatibilitySentinel = "skip_thought_signature_validator"'
Assert-Contains 'Gemini compatibility fallback is forbidden on official Google endpoints' $llmClient 'RequiresGeminiToolSignature() && !_capabilities.IsOfficialGoogle'
Assert-Contains 'Non-stream Gemini aliases and missing gateway metadata normalize onto the first tool call' $llmClient 'EnsureGeminiThoughtSignature(calls, msg,'
Assert-Contains 'Streaming Gemini compatibility is configured by the shared client path' $llmClient 'AllowGeminiSignatureCompatibilityFallback = AllowsGeminiSignatureCompatibilityFallback()'
Assert-Contains 'Gemini compatibility use remains observable in LLM metrics' $llmClient 'gemini_signature_compat'
Assert-Contains 'gcli root endpoint is normalized to its OpenAI v1 surface' $llmClient 'string.Equals(configured.Host, "gcli.ggchan.dev"'
Assert-Contains 'gcli root endpoint appends the documented v1 prefix' $llmClient 'b += "/v1";'
$streamingToolCollector2 = Read-Source 'src/JianghuYouling.Core/Llm/StreamingToolCollector.cs'
Assert-Contains 'Streaming Gemini assistant-level signatures are captured before final validation' $streamingToolCollector2 'FindGeminiThoughtSignatureFromAssistantEnvelope(delta)'
Assert-Contains 'Streaming Gemini missing-signature fallback is opt-in rather than globally enabled' $streamingToolCollector2 'AllowGeminiSignatureCompatibilityFallback, out _'
Assert-Contains 'Gemini envelope alias search explicitly excludes tool_calls' $llmClient 'signature attached to the second parallel call can never be borrowed by the first'
# #12/#13 冷归档与连载 Clear 删除顺序:main 最后删,避免孤 .bak 复活。
$coldArchiveStore = Read-Source 'src/JianghuYouling.Core/Persistence/ConversationColdArchiveStore.cs'
Assert-Contains 'Cold archive delete uses the complete artifact set and deletes main last' $coldArchiveStore 'DurableFileStore.TryDeleteAllArtifacts(path)'
Assert-Contains 'Saga clear uses the complete artifact set and deletes main last' $eventSagaStore 'DurableFileStore.TryDeleteAllArtifacts(path)'
# #4/#5 群聊清空前置失败快照回滚 + 墓碑推迟到空文档提交后。
Assert-Contains 'Group clear defines a pre-state restore for early failures' $groupChatOrchestrator 'void RestoreClearPreState()'
Assert-CountEquals 'Group clear restores pre-state on every pre-commit failure path' $groupChatOrchestrator 'RestoreClearPreState();' 4
Assert-Before 'Group clear writes deletion tombstones only after the empty document commits' $groupChatOrchestrator 'WriteDocumentAtomic(path, clearedDocument, ".tmp");' 'sharedDeleted.Add(line.Id)'
# #6 删归档轮重放对不可读段 fail-closed(三参传 mustResolveExchanges)。
Assert-Contains 'Pending refresh replay fails closed on unreadable archive segments' $groupChatOrchestrator 'TryRewriteArchiveSegmentsRemoving(pendingSet, new HashSet<string>(StringComparer.Ordinal), pendingSet)'
# #7 中断补 UI 收尾(停思考点+给在制轮控制条)。#9 退群去重同键页签。#10 头像扫描节流。
Assert-Match 'Interrupt finalizes the in-flight round UI (stop dots + control bar)' $chatWindow 'public void Interrupt\(\)[\s\S]{0,1600}EndStreamingReply\([\s\S]{0,500}FinalizeRound\(\)'
Assert-NotContains 'Closing a group never mutates it back into a source single tab' $chatWindow 'FindOtherWithSameKey(tab)'
Assert-Contains 'Assistant avatar attach scan is throttled, not per-frame' $assistantWidget '_nextAvatarScan'

if ($failures.Count -gt 0) {
    Write-Host 'Regression checks failed:'
    foreach ($failure in $failures) {
        Write-Host " - $failure"
    }
    exit 1
}

Write-Host 'Regression checks passed.'
